"use client";
import { ArtemisScope } from "./artemis-scope";
import Variant0 from "./components/research-sources/variants/01-overview";
export interface ArtemisResearchSourcesProps { className?: string;  }
export function ArtemisResearchSources({ className }: ArtemisResearchSourcesProps) { return <ArtemisScope className={`art:[&>*]:mx-auto ${className ?? ""}`}><Variant0/></ArtemisScope>; }

"use client";
// @zeus-internal
import { useId as useArtemisInstanceId } from "react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { forwardRef, useState } from "react";
import { ArtemisSegmentedTabs } from "../../../foundations/segmented-tabs";
import { ARTEMIS_EASE_OUT, ARTEMIS_SPRING_LAYOUT, ARTEMIS_SPRING_PRESS } from "../../../lib/ease";
type Kind = "Guide" | "Specification" | "Documentation";
type Filter = "All" | Kind;
type Source = {
    id: string;
    title: string;
    publisher: string;
    type: Kind;
    label: string;
    description: string;
    url: string;
};
const sources: readonly Source[] = [
    { id: "aria", title: "ARIA Authoring Practices Guide", publisher: "W3C", type: "Guide", label: "Pattern library", description: "Patterns and working examples for building accessible widgets, with keyboard behavior spelled out for each one.", url: "https://www.w3.org/WAI/ARIA/apg/" },
    { id: "wcag", title: "Web Content Accessibility Guidelines 2.2", publisher: "W3C", type: "Specification", label: "W3C Recommendation", description: "The success criteria most accessibility reviews are measured against, grouped by perceivable, operable, understandable, and robust.", url: "https://www.w3.org/TR/WCAG22/" },
    { id: "focus", title: "Understanding Focus Visible", publisher: "W3C", type: "Guide", label: "Understanding WCAG", description: "Why keyboard users need a clear focus indicator, and what counts as visible enough to pass.", url: "https://www.w3.org/WAI/WCAG22/Understanding/focus-visible.html" },
    { id: "motion", title: "prefers-reduced-motion", publisher: "MDN", type: "Documentation", label: "CSS reference", description: "The media feature for detecting when someone has asked their system to minimize non-essential motion.", url: "https://developer.mozilla.org/en-US/docs/Web/CSS/@media/prefers-reduced-motion" },
    { id: "dialog", title: "ARIA: dialog role", publisher: "MDN", type: "Documentation", label: "ARIA reference", description: "How to label a dialog, where focus should go when it opens, and how to return it when it closes.", url: "https://developer.mozilla.org/en-US/docs/Web/Accessibility/ARIA/Roles/dialog_role" },
    { id: "learn", title: "Learn Accessibility", publisher: "web.dev", type: "Guide", label: "Course", description: "A course covering semantics, focus, color, and motion, with short exercises you can try in the browser.", url: "https://web.dev/learn/accessibility" },
];
const filters: readonly Filter[] = ["All", "Guide", "Specification", "Documentation"];
const colors: Record<Kind, string> = { Guide: "art:border-blue-500/25 art:bg-blue-500/10 art:text-blue-700 art:dark:text-blue-300", Specification: "art:border-teal-500/25 art:bg-teal-500/10 art:text-teal-700 art:dark:text-teal-300", Documentation: "art:border-amber-500/25 art:bg-amber-500/10 art:text-amber-700 art:dark:text-amber-300" };

function SearchIcon({ className = "" }: {
    className?: string;
}) { return <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={`art:lucide art:lucide-search ${className}`.trim()} aria-hidden="true"><path d="m21 21-4.34-4.34"/><circle cx="11" cy="11" r="8"/></svg>; }
const SourceRow = forwardRef<HTMLLIElement, {
    source: Source;
    selected: boolean;
    toggle: () => void;
}>(function SourceRow({ source, selected, toggle }, ref) {
    const reduce = useReducedMotion();
    return <motion.li ref={ref} layout={reduce ? false : "position"} className={`art:relative art:flex art:gap-4 art:rounded-2xl art:border art:bg-background art:p-4 art:transition-colors art:duration-200 art:has-[button:focus-visible]:ring-2 art:has-[button:focus-visible]:ring-ring ${selected ? "art:border-foreground/30" : "art:border-border art:hover:border-foreground/15"}`} initial={{ opacity: 0, y: reduce ? 0 : 6 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, transition: { duration: 0.12, ease: "easeOut" } }} transition={{ duration: 0.25, ease: ARTEMIS_EASE_OUT }}>
    <span aria-hidden="true" className={`art:mt-0.5 art:grid art:size-6 art:shrink-0 art:place-items-center art:rounded-full art:border art:transition-colors art:duration-200 ${selected ? "art:border-foreground art:bg-foreground art:text-background" : "art:border-border"}`}><AnimatePresence initial={false}>{selected && <motion.span key="check" initial={{ opacity: 0, scale: reduce ? 1 : 0.4 }} animate={{ opacity: 1, scale: 1 }} exit={{ opacity: 0, scale: 0.4, transition: { duration: 0.1, ease: "easeOut" } }} transition={reduce ? { duration: 0 } : { type: "spring", stiffness: 480, damping: 24, mass: 0.7 }}><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-check art:size-3.5" aria-hidden="true"><path d="M20 6 9 17l-5-5"/></svg></motion.span>}</AnimatePresence></span>
    <div className="art:min-w-0 art:flex-1"><div className="art:flex art:flex-wrap art:items-center art:gap-2 art:text-muted-foreground art:text-xs"><span className={`art:rounded-full art:border art:px-2 art:py-0.5 art:font-medium ${colors[source.type]}`}>{source.type}</span><span>{source.publisher}</span><span aria-hidden="true">{"\u00B7"}</span><span>{source.label}</span></div>
      <a className="art:group art:relative art:z-10 art:mt-2 art:inline-flex art:max-w-full art:items-center art:gap-1.5 art:rounded-full art:font-medium art:text-sm art:outline-none art:hover:underline art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background" href={source.url} rel="noreferrer" target="_blank"><span className="art:truncate">{source.title}</span><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-arrow-up-right art:size-3.5 art:shrink-0 art:text-muted-foreground art:transition-transform art:group-hover:-translate-y-0.5 art:group-hover:translate-x-0.5" aria-hidden="true"><path d="M7 7h10v10"/><path d="M7 17 17 7"/></svg></a>
      <p className="art:mt-1.5 art:line-clamp-2 art:text-muted-foreground art:text-sm art:leading-relaxed">{source.description}</p></div>
    <button type="button" className="art:items-center art:justify-center art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:gap-2 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-ring art:focus-visible:ring-offset-background art:inline-block art:p-0 art:font-normal art:text-inherit art:hover:bg-transparent art:hover:text-inherit art:absolute art:inset-0 art:size-full art:cursor-pointer art:outline-none art:focus-visible:ring-0 art:focus-visible:ring-offset-0 art:rounded-2xl" aria-label={`${selected ? "Remove" : "Add"} ${source.title} ${selected ? "from" : "to"} context`} aria-pressed={selected} onClick={toggle}/>
  </motion.li>;
});
function SourceSearch({ query, onQueryChange }: {
    query: string;
    onQueryChange: (value: string) => void;
}) {
const artemisInstanceId = useArtemisInstanceId();

    const [focused, setFocused] = useState(false);
    return <div className="art:flex art:flex-col art:gap-1.5 art:my-5 art:w-full"><div data-state={focused ? "focused" : "idle"} className={`art:relative art:h-10 art:overflow-hidden art:rounded-full art:border art:bg-background art:transition-colors art:duration-200 ${focused ? "art:border-muted-foreground/40" : "art:border-border"}`}><span className="art:pointer-events-none art:absolute art:left-3 art:top-1/2 art:flex art:-translate-y-1/2 art:items-center art:text-muted-foreground art:[&_svg]:h-4 art:[&_svg]:w-4"><SearchIcon /></span><input id={`${artemisInstanceId}-R_2pbsnpfdb_`} type="search" aria-label="Search sources" placeholder="Search your sources…" className="art:peer art:h-full art:w-full art:bg-transparent art:text-sm art:leading-6 art:text-foreground art:caret-foreground art:outline-none art:placeholder:text-muted-foreground/60 art:pl-10 art:pr-3.5" value={query} onChange={event => onQueryChange(event.target.value)} onFocus={() => setFocused(true)} onBlur={() => setFocused(false)}/></div><div className="art:contents"/></div>;
}
export default function ResearchSourcesOverview() {
const artemisInstanceId = useArtemisInstanceId();
const tabId = `${artemisInstanceId}-R_9bsnpfdb_`;

    const reduce = useReducedMotion();
    const [query, setQuery] = useState("");
    const [filter, setFilter] = useState<Filter>("All");
    const [selected, setSelected] = useState<readonly string[]>(["aria", "motion"]);
    const terms = query.trim().toLowerCase().split(/\s+/).filter(Boolean);
    const visible = sources.filter(source => (filter === "All" || source.type === filter) && terms.every(term => `${source.title} ${source.publisher} ${source.description}`.toLowerCase().includes(term)));
    const selectedSources = sources.filter(source => selected.includes(source.id));
    const toggle = (id: string) => setSelected(current => current.includes(id) ? current.filter(value => value !== id) : [...current, id]);
    const resetFilters = () => { setQuery(""); setFilter("All"); };
    const activeIndex = filters.indexOf(filter);
    return <section aria-label="Research sources" className="art:w-full art:max-w-2xl art:rounded-3xl art:border art:border-border art:bg-background art:p-5 art:@min-[640px]/artemis:p-6">
    <header className="art:flex art:items-start art:justify-between art:gap-4"><div className="art:min-w-0"><p className="art:mb-1 art:text-muted-foreground art:text-xs">{"Sources & references"}</p><h2 className="art:font-medium art:text-xl">{"Building accessible interfaces"}</h2><p className="art:mt-1.5 art:text-muted-foreground art:text-sm">{"Pick the references your assistant should read before it answers."}</p></div><span className="art:grid art:size-10 art:shrink-0 art:place-items-center art:rounded-full art:bg-muted"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-book-open art:size-4" aria-hidden="true"><path d="M12 5v16"/><path d="M20.001 19A2 2 0 0022 17V5a2 2 0 00-1.999-2L16 3.002A5 5 0 0012 5a5 5 0 00-4-2H4a2 2 0 00-2 2v12a2 2 0 001.999 2H8a5 5 0 014 2 5 5 0 014-2z"/></svg></span></header>
    <SourceSearch query={query} onQueryChange={setQuery}/>
    <div className="art:mb-3 art:flex art:flex-wrap art:items-center art:justify-between art:gap-3"><div><ArtemisSegmentedTabs layout="position" items={filters.map((value, index) => ({ value, label: value, id: `${tabId}-${index}`, ariaControls: `${tabId}-results` }))} value={filter} onValueChange={value => setFilter(value as Filter)} listClassName="art:inline-flex art:items-center art:gap-1 art:rounded-full art:bg-muted art:p-1 art:flex-wrap" buttonClassName="art:rounded-full art:text-xs" ariaLabel="Source type" roving/></div><p aria-live="polite" className="art:text-muted-foreground art:text-xs">{visible.length}{" of "}{sources.length}</p></div>
    <div aria-labelledby={`${tabId}-${activeIndex}`} className="art:min-h-60" id={`${tabId}-results`} role="tabpanel">{visible.length ? <ul className="art:space-y-2"><AnimatePresence mode="popLayout" initial={false}>{visible.map(source => <SourceRow key={source.id} source={source} selected={selected.includes(source.id)} toggle={() => toggle(source.id)}/>)}</AnimatePresence></ul> : <motion.div className="art:flex art:flex-col art:items-center art:rounded-2xl art:border art:border-dashed art:border-border art:px-5 art:py-12 art:text-center" initial={reduce ? false : { opacity: 0, y: 6 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: reduce ? 0 : 0.25, ease: ARTEMIS_EASE_OUT }}><span className="art:grid art:size-11 art:place-items-center art:rounded-full art:bg-muted"><SearchIcon className="art:size-4 art:text-muted-foreground"/></span><p className="art:mt-4 art:font-medium art:text-sm">No matching sources</p><p className="art:mt-1 art:text-muted-foreground art:text-sm">Try another search or source type.</p><motion.button whileHover={reduce ? undefined : { scale: 1.01 }} whileTap={reduce ? undefined : { scale: 0.99 }} transition={ARTEMIS_SPRING_PRESS} type="button" className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:border art:border-border art:bg-transparent art:text-foreground art:hover:bg-primary/5 art:gap-2 art:px-5 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:h-9 art:mt-4 art:rounded-full" tabIndex={0} onClick={resetFilters}>Clear filters</motion.button></motion.div>}</div>
    <footer className="art:mt-4 art:flex art:flex-wrap art:items-center art:gap-3 art:border-border art:border-t art:pt-4"><output aria-live="polite" className="art:flex art:items-center art:gap-1 art:text-muted-foreground art:text-xs art:tabular-nums"><span className="art:relative art:inline-flex art:overflow-hidden art:font-medium art:text-foreground"><AnimatePresence mode="popLayout" initial={false}><motion.span key={selected.length} initial={{ opacity: 0, y: reduce ? "0%" : "100%" }} animate={{ opacity: 1, y: "0%" }} exit={{ opacity: 0, y: reduce ? "0%" : "-100%" }} transition={{ duration: 0.22, ease: ARTEMIS_EASE_OUT }}>{selected.length}</motion.span></AnimatePresence></span>{" "}{selected.length === 1 ? "source" : "sources"}{" in context"}</output>
      <ul className="art:flex art:min-w-0 art:flex-1 art:flex-wrap art:items-center art:gap-1.5"><AnimatePresence mode="popLayout" initial={false}>{selectedSources.slice(0, 3).map(source => <motion.li key={source.id} layout={reduce ? false : "position"} className="art:flex art:max-w-48 art:items-center art:gap-1 art:rounded-full art:border art:border-border art:py-0.5 art:pr-0.5 art:pl-2.5 art:text-xs" initial={{ opacity: 0, scale: reduce ? 1 : 0.8 }} animate={{ opacity: 1, scale: 1 }} exit={{ opacity: 0, scale: reduce ? 1 : 0.8 }} transition={reduce ? { duration: 0 } : ARTEMIS_SPRING_LAYOUT}><span className="art:truncate">{source.title}</span><motion.button whileHover={reduce ? undefined : { scale: 1.01 }} whileTap={reduce ? undefined : { scale: 0.99 }} transition={ARTEMIS_SPRING_PRESS} type="button" className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:text-muted-foreground art:hover:bg-primary/5 art:hover:text-foreground art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:size-6 art:shrink-0 art:rounded-full" aria-label={`Remove ${source.title} from context`} tabIndex={0} onClick={() => setSelected(current => current.filter(id => id !== source.id))}><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-x art:size-3" aria-hidden="true"><path d="M18 6 6 18"/><path d="m6 6 12 12"/></svg></motion.button></motion.li>)}{selectedSources.length > 3 && <motion.li key="more" layout={reduce ? false : "position"} className="art:px-1 art:text-muted-foreground art:text-xs" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}>+{selectedSources.length - 3}{" more"}</motion.li>}</AnimatePresence></ul>
      <motion.button whileHover={reduce ? undefined : { scale: 1.01 }} whileTap={reduce ? undefined : { scale: 0.99 }} transition={ARTEMIS_SPRING_PRESS} type="button" className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:text-muted-foreground art:hover:bg-primary/5 art:hover:text-foreground art:gap-2 art:px-5 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:h-9 art:rounded-full" tabIndex={0} disabled={selected.length === 0} onClick={() => setSelected([])}>Clear</motion.button></footer>
  </section>;
}
